from construire import p, refs, table, window, DX

def dossier(title,definition,procedure,example,pitfall,source,extra=''):
 return window(title,p(definition)+p(procedure)+p('La vignette suivante est fictive. '+example)+p('Le piège consiste à '+pitfall)+extra+refs(*source))

def sections_a():
 s=[]
 s.append((
 'Le SSP O7.4 étudie comment les conditions de vie, les relations et les expositions modifient l’expérience et la prise en charge d’une maladie chronique. Le médecin recherche les ressources autant que les obstacles et élabore le projet avec la personne concernée. Ce cadre complète l’évaluation somatique ; il ne justifie pas de qualifier de psychogène un symptôme inexpliqué.',
 dossier('Le cadre PROFILES relie la clinique, le social et la prévention.',
 'PROFILES définit des situations de départ que le jeune médecin doit savoir évaluer de façon structurée. Les dimensions sociales et préventives appartiennent au mandat clinique, y compris lorsqu’une maladie organique est déjà connue.',
 'Le médecin part de ce qui amène la personne aujourd’hui. Il différencie le problème médical, le retentissement dans la vie réelle et l’obstacle qui empêche une action utile. Il demande ensuite quelle amélioration aurait le plus de valeur pour le patient.',
 'Une personne de 58 ans, suivie pour une maladie respiratoire, demande un certificat. Elle rapporte une fatigue, mais explique surtout qu’elle ne peut plus rejoindre son poste à pied. Le médecin examine la fatigue et documente le trajet avant de conclure à une incapacité globale.',
 'réduire le problème à un diagnostic déjà inscrit au dossier, alors que la demande porte aussi sur une activité et un environnement.',['S01'])+
 dossier('L’autogestion s’appuie sur des ressources et ne transfère pas la responsabilité au malade.',
 'L’Office fédéral de la santé publique (OFSP) décrit un soutien conjoint par les personnes concernées, leurs proches et les professionnels. Le but est de rendre les décisions et les actions quotidiennes possibles, et non de demander au patient de remplacer l’équipe soignante.',
 'Le médecin identifie ce que la personne sait déjà faire, ce qu’elle souhaite apprendre et l’aide dont elle dispose. Une tâche réalisable est choisie avec elle. L’équipe vérifie ensuite ce qui a effectivement changé et ajuste le soutien.',
 'Une femme de 62 ans dispose de ses médicaments mais ne distingue pas leurs horaires. Elle choisit de vérifier son plan avec une infirmière et sa sœur, qu’elle accepte d’associer. Le résultat attendu est une démonstration correcte de l’utilisation du plan, et non une simple signature de réception.',
 'confondre autonomie, indépendance complète et absence de besoin d’aide.',['S02','S03'])+
 table(['La notion est précisée.','Le médecin la distingue.','La décision en découle.'],[
 ['La maladie décrit une affection ou une atteinte de santé.','Le retentissement décrit ce que la personne ne peut plus faire ou vivre comme elle le souhaite.','Le traitement et les aménagements sont discutés ensemble.'],
 ['L’environnement comprend le logement, le travail, les conditions physiques et l’accès aux ressources.','Une exposition peut aggraver une maladie sans en expliquer tous les symptômes.','L’examen clinique demeure nécessaire avant toute attribution causale.'],
 ['Le soutien social correspond à une aide disponible et acceptée.','La présence d’un proche ne garantit ni sa disponibilité ni l’accord du patient.','La personne précise qui peut être associé et à quelles informations.']
 ])))
 s.append((
 'Les indicateurs suisses décrivent des populations et des périodes différentes ; ils ne permettent pas de classer les dix scénarios par fréquence chez les malades chroniques. La fiche HLS19–21 rapporte 49 % d’adultes ayant des difficultés fréquentes avec les informations de santé ; une autre fiche rapporte de faibles compétences d’autogestion chez 66 % des personnes présentant une maladie chronique. En 2024, le renoncement financier à des soins médicaux ou dentaires nécessaires concernait 5,5 % des personnes de 16 ans et plus.',
 table(['L’indicateur est daté.','La population est définie.','La valeur est lue.','La limite est expliquée.'],[
 ['La fiche sur la littératie exploite l’enquête réalisée en 2020.','Les 2 502 participants avaient 18 ans ou plus et résidaient en Suisse.','49 % rapportaient des difficultés fréquentes avec les informations de santé. [S05]','Cette proportion ne constitue ni un test individuel ni la prévalence d’une barrière linguistique.'],
 ['La fiche HLS19–21 porte aussi sur l’autogestion.','L’analyse concerne les répondants qui présentaient une maladie chronique.','66 % avaient des compétences d’autogestion classées faibles. [S06]','La mesure est autodéclarée et ne prouve pas une incapacité à consentir.'],
 ['MonAM publie en 2026 les données SILC 2024.','L’indicateur concerne les personnes de 16 ans et plus.','5,5 % ont renoncé pour une raison financière à des soins nécessaires médicaux ou dentaires. [S04]','La série a été révisée ; une variation ne doit pas être interprétée sans examiner la méthode.'],
 ['L’enquête mandatée sur les aidants portait sur 2018.','Le périmètre comprend les proches qui assistent ou soignent un membre dépendant.','Le nombre estimé était de 592 000 personnes, dont environ 49 000 de 9 à 15 ans. [S08]','Ce nombre ne mesure pas l’épuisement et ne représente pas un recensement de 2026.'],
 ['Le monitorage thermique examine mai à septembre 2025.','L’estimation porte sur les décès attribuables à la chaleur en Suisse.','410 décès étaient attribués à la chaleur ; 84 % concernaient les plus de 75 ans. [S12]','Une attribution populationnelle ne démontre pas la cause du décès d’un patient donné.'],
 ['L’OFEV publie une estimation nationale en 2025.','L’estimation concerne la charge de la pollution atmosphérique.','L’ordre de grandeur est d’environ 2 000 décès prématurés annuels. [S13]','Il ne faut pas le convertir en probabilité clinique personnelle sans modèle applicable.']
 ])+
 dossier('Le dénominateur doit être lu avant le pourcentage.',
 'Une fréquence n’a de sens qu’avec une population, une période, une méthode et une définition. Un nombre de proches aidants, une proportion de répondants et une estimation de décès attribuables répondent à des questions différentes.',
 'Le lecteur identifie le dénominateur et la question posée, puis vérifie si le résultat s’applique au cas. Il cite la période des données séparément de la date de publication. Il n’utilise pas une donnée ancienne comme si elle mesurait la situation actuelle.',
 'Un étudiant affirme que 49 % des personnes malades chroniques ne comprennent pas leur traitement. Il doit corriger cette phrase : la fiche citée décrit des adultes de la population résidente et leurs difficultés avec l’information de santé ; elle n’observe pas directement leur prise de médicaments.',
 'transformer une association populationnelle en diagnostic, en causalité personnelle ou en classement de scénarios.',['S04','S05','S06'])+
 p('Les prévalences suisses comparables de dépression parmi les malades chroniques, d’épuisement des aidants et de difficultés de transition chez les adolescents n’ont pas été établies par les sources ouvertes de cette session. Les incidences et mortalités propres aux scénarios sociaux sont sans objet lorsqu’ils ne constituent pas des maladies ; les données manquantes ne sont pas remplacées par zéro.')))
 s.append((
 'Le consentement, la confidentialité, les droits sociaux et la protection du travail déterminent une partie de la conduite. Le droit suisse distingue la capacité de discernement, l’aide acceptée et la représentation d’une personne incapable de discernement. Le mécanisme explicatif reste celui de la situation : un obstacle financier, organisationnel ou physique peut empêcher un soin pourtant indiqué.',
 dossier('Le discernement est évalué pour une décision précise et à un moment donné.',
 'L’article 16 du Code civil (CC) définit la capacité d’agir raisonnablement. Les directives de l’Académie Suisse des Sciences Médicales (ASSM) demandent d’examiner les capacités de compréhension, d’évaluation personnelle, de formation et de concrétisation de la volonté lorsqu’un doute fondé existe.',
 'Le médecin optimise d’abord les conditions de communication. Il explique la décision, demande au patient d’en exposer les conséquences pour lui et recherche une volonté personnelle. Si les capacités semblent fortement limitées, il documente les raisons, la décision concernée, le moment et les soutiens mobilisés. Un désaccord avec le médecin ne suffit pas à conclure à l’incapacité.',
 'Un homme de 73 ans refuse une intervention pour pouvoir rester à domicile. Il décrit correctement les bénéfices, les risques et les solutions alternatives, puis maintient son choix. Le médecin ne déduit pas une incapacité du seul refus ; il vérifie et documente le raisonnement dans les conditions du cas.',
 'assimiler âge, maladie psychiatrique, faible littératie ou besoin d’interprète à une incapacité de discernement.',['S17','S24'])+
 dossier('Le secret professionnel reste applicable lorsque le proche veut aider.',
 'L’article 321, chiffres 1 à 3, du Code pénal (CP) protège les informations apprises dans l’exercice professionnel. Son chiffre 2 prévoit le consentement de l’intéressé ou l’autorisation écrite de l’autorité compétente ; son chiffre 3 réserve les dispositions légales particulières.',
 'Le médecin précise avec la personne qui peut recevoir quelles informations et dans quel but. Il transmet ce qui est nécessaire au mandat convenu. Une éventuelle obligation cantonale de signalement doit être vérifiée selon le lieu et la situation ; le seul intérêt d’un proche ou d’un employeur ne constitue pas une autorisation.',
 'La fille d’une patiente demande par téléphone le détail de son dossier pour organiser les soins. Le médecin vérifie l’identité, recherche l’accord de la patiente ou une base de représentation applicable et convient d’une information utile. Il n’envoie pas le dossier complet par défaut.',
 'considérer qu’une participation pratique aux soins donne automatiquement accès à toutes les données médicales.',['S28','S24'])+
 table(['L’obstacle ou la perturbation est identifié.','L’exploration l’éclaire.','Le levier en modifie le mécanisme.'],[
 ['Le coût empêche l’achat ou la consultation.','Le médecin demande ce qui a été reporté et vérifie les montants avec la personne.','Le service social explore les droits et les solutions de paiement ; le plan thérapeutique tient compte de l’accès réel.'],
 ['La langue ou la complexité empêche la compréhension.','Le patient reformule une action et ses raisons dans une langue qu’il maîtrise.','L’interprète et un message adapté réduisent l’erreur de transmission.'],
 ['La charge d’aide dépasse les ressources disponibles.','L’outil OFSP décrit les tâches, la charge subjective et les relais.','Une décharge concrète réduit la tâche que l’aidant ne peut plus assurer.'],
 ['La chaleur ou un polluant aggrave les contraintes physiques.','L’entretien relie la chronologie d’exposition à l’examen et aux mesures pertinentes.','Le traitement de la décompensation et la réduction d’exposition agissent sur deux leviers distincts.']
 ])+refs('S07','S09','S11','S16')))
 s.append((
 'La première question porte sur un danger médical, psychique ou de protection qui ne peut pas attendre. Le médecin examine ensuite les explications somatiques, les effets du traitement et les contraintes de vie, puis retient une formulation partagée. Plusieurs scénarios peuvent coexister : la liste des DX ne force jamais un choix exclusif.',
 table(['L’hypothèse dangereuse est envisagée.','L’élément discriminant est recherché.','Le piège est évité.','La décision est orientée.'],[
 ['Une décompensation somatique peut expliquer la fatigue ou le retrait.','Le début, le retentissement, l’examen ciblé et les examens indiqués sont confrontés au récit.','Le médecin n’attribue pas un symptôme nouveau à l’anxiété sans évaluation.','La gravité détermine l’orientation médicale avant le travail social.'],
 ['Une détresse psychique peut menacer la sécurité.','Le médecin interroge directement l’idée de mort, l’intention, l’accès à des moyens et les ressources de protection.','Un questionnaire ou un déni isolé ne ferme pas l’évaluation.','Le besoin de protection et de soins spécialisés est organisé selon l’état présent.'],
 ['Une incapacité à agir peut venir d’un obstacle de communication.','L’entretien est repris avec une communication adaptée et, si nécessaire, un interprète.','Le médecin ne confond pas erreur de langue et défaut de discernement.','L’évaluation de la volonté est faite après la levée des obstacles corrigeables.'],
 ['Un proche peut être épuisé ou une personne dépendante peut être en danger.','Les entretiens séparés précisent la charge, les besoins non couverts et les conflits.','Un récit familial unique ne remplace pas la parole de la personne concernée.','L’équipe met en place un relais sûr et vérifie la base légale si une protection est envisagée.'],
 ['Une exposition au logement ou à la chaleur peut être contributive.','La chronologie, le lieu, les autres personnes exposées et l’examen sont mis en relation.','La présence d’une exposition n’exclut pas une autre cause médicale.','L’urgence et l’enquête environnementale sont menées selon leurs indications propres.']
 ])+refs('S17','S21','S11','S16')+
 dossier('La formulation situationnelle doit pouvoir être contredite.',
 'Une hypothèse utile décrit un obstacle observable, son retentissement et ce qui permettrait de le vérifier. Elle ne remplace pas une conclusion médicale que les données ne permettent pas encore de poser.',
 'Le médecin écrit ce qu’il sait, ce que la personne rapporte et ce qu’il doit encore vérifier. Il recherche un fait qui soutient ou fragilise chaque explication. Il annonce ensuite au patient la prochaine étape et la condition qui ferait changer l’orientation.',
 'Un patient de 47 ans manque deux rendez-vous. L’équipe envisage d’abord un désengagement. L’entretien montre que les horaires coïncident avec les seuls transports disponibles pour accompagner son enfant. L’hypothèse change et la consultation est organisée autrement.',
 'écrire « non observant » comme une explication complète sans explorer coût, langue, transport, effets indésirables et préférences.',['S02','S07','S19'])))
 s.append((
 'L’entretien commence par la priorité du patient et l’effet de la maladie sur une journée ordinaire. Il explore ensuite compréhension, traitement réel, budget, logement, travail, relations, charge d’aide et expositions. Les questions sensibles sont posées avec tact, dans un espace où la personne peut répondre sans être contrôlée par un tiers.',
 table(['La question est posée.','Sa raison est expliquée.','La réponse fait agir.'],[
 ['« Qu’est-ce qui vous empêche le plus de faire ce qui compte pour vous ? »','Le médecin recherche une activité et un but définis par la personne.','Le premier objectif est négocié à partir d’un besoin vécu.'],
 ['« Montrez-moi comment vous utilisez ce plan quand vous êtes chez vous. »','La démonstration vérifie l’usage réel, au-delà de l’accord poli.','Le plan est simplifié ou un soutien est organisé si l’étape ne peut pas être réalisée.'],
 ['« Avez-vous reporté un soin, un médicament ou un déplacement parce que vous ne pouviez pas le payer ? »','La question sépare choix, coût et obstacle d’accès.','Les soins nécessaires et les droits financiers sont examinés sans promettre une prise en charge automatique.'],
 ['« Qui peut vous aider aujourd’hui, et cette personne est-elle d’accord ? »','La disponibilité théorique ne garantit pas une aide concrète.','Le médecin identifie un relais accepté et le besoin de décharge.'],
 ['« Quelles tâches de travail restent possibles et lesquelles vous mettent en difficulté ? »','La fonction est comparée aux exigences du poste.','Le certificat précise le retentissement médical pertinent et un plan de réévaluation.'],
 ['« Les difficultés changent-elles selon la pièce, le bâtiment, l’heure ou la météo ? »','La chronologie oriente une contribution environnementale.','L’enquête et la réduction d’exposition sont ciblées.'],
 ['« Vous arrive-t-il de penser que vous ne souhaitez plus vivre ? »','Une détresse peut ne pas être exprimée spontanément.','La réponse ouvre une évaluation clinique et un plan de sécurité adapté.']
 ])+refs('S02','S04','S09','S16','S19','S21')+
 dossier('Les drapeaux rouges ouvrent une réponse immédiate et un relais confirmé.',
 'Une altération aiguë de la conscience, une détresse clinique, une mise en danger psychique ou l’impossibilité d’assurer un besoin vital rendent insuffisante une simple orientation différée. Le point de départ est l’état actuel, pas l’étiquette sociale.',
 'Le médecin évalue immédiatement la sécurité et la gravité. Une altération de la conscience ou l’impossibilité de boire dans un contexte de chaleur impose l’appel au 144 et le rafraîchissement en attendant les secours ; aucune boisson n’est donnée à une personne inconsciente. En cas de danger psychique, le médecin évalue directement la suicidalité et organise immédiatement le relais clinique nécessaire, sans conclure à une sécurité garantie par un score. Si une personne n’est pas capable de décider et que les soins sont urgents, l’article 379 CC renvoie à sa volonté présumée et à ses intérêts. La documentation distingue les faits observés et les raisons de la décision.',
 'Une patiente de 81 ans, seule dans un appartement chaud, ne répond plus de façon cohérente. Le médecin ne se contente pas de laisser une recommandation de boire et un numéro de téléphone. Il organise l’aide urgente, le rafraîchissement et une évaluation clinique ; le traitement précis dépend des constatations.',
 'considérer qu’un bon réseau habituel ou une évaluation ancienne garantit la sécurité présente.',['S11','S32','S24','S21'])))
 s.append((
 'Le normal est recherché avant la description d’une anomalie : la personne reste attentive, échange dans des conditions adaptées et peut décrire une action quotidienne. L’examen se concentre ensuite sur les plaintes, les maladies connues, les traitements et l’exposition. Une mesure clinique n’explique pas à elle seule un obstacle social ; un obstacle social ne dispense pas d’examen.',
 table(['La région ou la fonction est examinée.','Le résultat normal est recherché.','L’écart conduit à une évaluation.','La limite est rappelée.'],[
 ['L’état général et les fonctions vitales sont évalués selon la plainte.','Le patient ne présente pas de détresse observée et peut participer à l’entretien.','Une dégradation aiguë fait prioriser la prise en charge médicale.','Une consultation calme n’exclut pas une difficulté à domicile.'],
 ['L’attention, le comportement et la communication sont observés.','Le patient suit l’échange et peut préciser sa décision avec les aides adaptées.','Une rupture attentionnelle, une confusion ou un changement récent fait rechercher une cause clinique.','Une langue différente ne constitue pas une anomalie cognitive.'],
 ['La fonction respiratoire et cardiovasculaire est examinée si les symptômes le justifient.','L’examen décrit le confort, le rythme observé et la tolérance de l’activité disponible.','Une dyspnée ou un malaise nouveau appelle un bilan orienté par la gravité.','La pollution ou l’anxiété ne sont pas des diagnostics d’exclusion automatiques.'],
 ['La mobilité et les gestes utiles sont évalués avec l’accord du patient.','Le patient réalise sans difficulté la tâche réellement pertinente pour son projet.','Une limitation est décrite avec le geste, le contexte et l’aide nécessaire.','L’impossibilité d’un geste ne permet pas d’inférer toute la capacité professionnelle.'],
 ['La situation du proche est abordée avec son accord.','Le proche décrit des tâches compatibles avec ses ressources et des relais disponibles.','Une charge devenue insoutenable fait organiser une décharge et évaluer sa santé.','Le médecin n’établit pas le diagnostic médical du proche absent à partir d’un récit unique.']
 ])+refs('S09','S11','S17','S19')+
 dossier('Un signe observé doit être décrit avec sa méthode et son contexte.',
 'Une observation utile est reproductible dans le contexte clinique : le médecin indique ce qu’il demande, ce qu’il observe et ce qu’il ne peut pas conclure. Le dossier ne transforme pas une impression en test validé.',
 'Le médecin explique le geste et recueille l’accord. Il compare le résultat à la tâche concrète du quotidien et recherche un changement par rapport à l’état habituel. Si une difficulté apparaît, il précise les symptômes et choisit un examen approprié plutôt qu’une batterie systématique.',
 'Un homme de 56 ans peut se lever d’une chaise au cabinet mais rapporte qu’il ne peut pas porter les charges de son poste. Le médecin décrit les deux informations et demande la nature du port de charge. Il ne transforme pas la réussite au cabinet en aptitude professionnelle générale.',
 'attribuer une sensibilité ou une spécificité inventée à une observation fonctionnelle non standardisée.',['S19','S17'])))
 s.append((
 'Les syndromes situationnels regroupent des signes fonctionnels rapportés et des éléments objectivables, sans inventer une nouvelle classification diagnostique. Leur rôle est d’organiser l’entretien et les priorités. Chaque signe garde sa propre explication possible et sa limite.',
 syndrome_windows()+table(['Le syndrome de travail est nommé.','Le signe fonctionnel est rapporté.','L’élément objectivable est recherché.','Le lien explicatif est discuté.'],[
 ['7.1 — Le parcours de soins devient difficile à réaliser.','Le patient dit qu’il reporte les rendez-vous ou qu’il ne sait pas quoi faire.','L’équipe vérifie avec lui les étapes qui ont échoué et les aides accessibles.','La charge du parcours peut dépasser les ressources disponibles.'],
 ['7.2 — Le soutien devient insuffisant.','Le patient se sent seul ou l’aidant dit qu’il ne pourra plus continuer.','L’entretien vérifie l’aide effectivement disponible, la fréquence des tâches et les besoins non couverts.','Le besoin de soutien et les ressources ne correspondent plus.'],
 ['7.3 — L’exposition physique aggrave la vulnérabilité.','La personne décrit un malaise lors de chaleur ou une gêne liée à un lieu.','Le médecin examine les symptômes et confronte chronologie, environnement et mesures adaptées.','Une exposition contributive s’ajoute à une maladie sans en prouver la cause unique.'],
 ['7.4 — La participation professionnelle ou scolaire se réduit.','La personne ne peut plus assumer certaines tâches ou craint la rupture de suivi.','L’équipe compare les exigences concrètes, les capacités et les possibilités d’aménagement.','L’environnement et l’organisation des soins peuvent amplifier ou réduire la limitation.']
 ])+refs('S02','S09','S10','S11','S18','S19')+
 dossier('Le retrait social doit être distingué d’une préférence pour la solitude.',
 'L’indicateur Obsan décrit une expérience subjective de relations insuffisantes. Une personne peut vivre seule sans souffrir de solitude ; une personne très entourée peut se sentir seule.',
 'Le médecin demande si la situation est choisie et satisfaisante. Il explore le besoin de contact, les obstacles à la relation et la possibilité d’obtenir de l’aide en cas de difficulté. Une intervention sociale se construit à partir du souhait de la personne, avec une évaluation clinique si la détresse le justifie.',
 'Une femme de 69 ans vit seule et apprécie sa tranquillité. Elle accepte un appel de contrôle pendant une période de chaleur, mais ne souhaite pas participer à un groupe. Le médecin respecte ce choix et vérifie que le moyen de demander de l’aide fonctionne.',
 'utiliser le nombre de visites comme un diagnostic de solitude ou prescrire une activité sociale sans recueillir les préférences.',['S10','S11'])))
 s.append((
 'Le diagnostic situationnel nomme le problème, le retentissement, l’obstacle et les ressources, avec leur niveau de certitude. Aucun seuil unique ne pose le diagnostic d’« aspect psychosocial d’une maladie chronique ». Les diagnostics médicaux et les décisions juridiques suivent leurs critères propres.',
 dossier('Une formulation partagée peut être vérifiée à la consultation suivante.',
 'Le médecin rassemble les informations en une phrase utilisable : la maladie ou le symptôme rencontré, la tâche qui échoue, l’obstacle documenté et l’action choisie. Le patient peut la corriger. Une formulation utile inclut aussi ce qui fonctionne déjà.',
 'Le médecin demande l’accord sur la description, puis distingue problème prioritaire et problèmes secondaires. Il note une action, un responsable, une échéance adaptée au risque et un résultat observable. Cette structure est un outil pédagogique de documentation, pas une échelle validée.',
 'Une patiente de 64 ans dit : « Je sais pourquoi je dois venir, mais je ne peux pas payer le transport. » La formulation retient un obstacle de transport dans un suivi compris, plutôt qu’une faible littératie supposée. Le service social vérifie une solution avec elle.',
 'faire passer une grille de travail locale pour un critère officiel ou demander une certitude artificielle.',['S02','S04'])+
 table(['La situation est établie.','Ce qui suffit est précisé.','Ce qui ne suffit pas est rejeté.'],[
 ['Un obstacle financier est retenu.','Le patient décrit un renoncement concret et la raison financière est explicitée.','Un revenu supposé faible ne permet pas de déduire la cause d’un rendez-vous manqué.'],
 ['Une difficulté de communication est retenue.','Une consigne importante ne peut pas être correctement transmise ou utilisée dans les conditions de l’entretien.','Une origine étrangère ne permet pas d’inférer les compétences de santé.'],
 ['Un besoin de décharge de l’aidant est retenu.','L’évaluation décrit les tâches, la charge ressentie et l’aide supplémentaire nécessaire.','Le nombre d’heures ne pose pas à lui seul un diagnostic psychiatrique.'],
 ['Une incapacité de discernement est envisagée.','Des limitations significatives sont constatées pour une décision définie, après soutien des capacités.','Le refus de la recommandation, une fragilité sociale ou un score cognitif isolé ne suffisent pas.'],
 ['Une contribution environnementale est envisagée.','La chronologie et des éléments cliniques ou environnementaux compatibles soutiennent l’hypothèse.','Une concentration mesurée ne démontre pas seule la cause de tous les symptômes.']
 ])+refs('S04','S07','S09','S16','S17')))
 s.append((
 'Il n’existe pas de gold standard biologique pour ce SSP transversal. L’entretien et l’examen ciblés constituent la première intention ; les outils structurent une question précise et ne remplacent pas le jugement clinique. Une seconde intention n’est engagée que si elle peut modifier la conduite ou résoudre une incertitude pertinente.',
 table(['L’outil est prescrit pour une question.','La préparation est adaptée.','Le résultat est interprété.','La conduite est définie.'],[
 ['L’entretien vérifie une information essentielle ou un obstacle.','Le médecin choisit un espace confidentiel, une langue et des supports adaptés.','Une reformulation correcte montre ce qui a été compris dans ces conditions.','Une erreur fait reprendre le message ou organiser un soutien ; elle ne prouve pas l’incapacité.'],
 ['L’outil OFSP examine le besoin de décharge du proche.','Le proche décrit les tâches et sa charge ; le médecin recherche les divergences.','Les catégories décrivent des besoins et des soutiens ; aucun seuil diagnostique de burnout n’est inventé.','Des mesures prioritaires et un moment de réévaluation sont convenus.'],
 ['L’évaluation du discernement répond à un doute fondé.','Les obstacles de communication sont corrigés et la décision est expliquée.','Les capacités nécessaires à cette décision sont documentées, avec les éléments contradictoires.','L’ASSM propose une approche clinique structurée ; une complexité peut justifier un avis spécialisé.'],
 ['Les examens somatiques explorent une plainte ou un signe.','La prescription précise l’indication et les contraintes personnelles.','Les résultats sont confrontés à la probabilité clinique et au changement d’état.','Un résultat discordant déclenche une réévaluation de l’hypothèse, pas une attribution psychogène automatique.'],
 ['L’enquête du logement explore une exposition plausible.','La pièce, la période, les usages et les symptômes sont documentés avant une mesure ciblée.','Un résultat environnemental décrit une exposition dans les conditions de mesure.','Le médecin poursuit le bilan médical nécessaire et oriente la correction environnementale.']
 ])+refs('S07','S09','S16','S17')+
 dossier('Les situations particulières modifient l’outil, pas l’exigence de compréhension.',
 'La grossesse, l’âge, le développement, une difficulté sensorielle, une insuffisance d’organe ou un dispositif implanté peuvent modifier une investigation spécifique. Ces contraintes ne rendent pas automatiquement un entretien ou une aide sociale inadaptés.',
 'Le médecin précise la question avant de prescrire. S’il envisage un examen exposant à un risque particulier, il vérifie la recommandation et les alternatives de cet examen. Il ne prescrit pas d’imagerie ou de produit de contraste pour explorer un problème social sans indication médicale.',
 'Une personne enceinte décrit une difficulté financière sans signe somatique nouveau. L’entretien et l’aide au parcours sont adaptés à sa situation. Le médecin ne lui propose pas un examen irradiant au seul motif que le cours comporte une rubrique « explorations ».',
 'inventer une alternative technique ou un seuil de fonction rénale qui n’a pas d’objet dans la situation.',['S01','S17'])+
 p('Les valeurs normales, sensibilités, spécificités et seuils sont sans objet pour une grille situationnelle non diagnostique. Lorsqu’un véritable test médical est indiqué, ses seuils et limites doivent être lus dans la source propre à ce test ; ils ne sont pas empruntés à ce SSP.')))
 s.append((
 'L’algorithme commence par la gravité et la sécurité, puis vérifie le consentement et les obstacles modifiables. Il organise une action concrète, un responsable et une réévaluation. Il reste ouvert à plusieurs scénarios simultanés.',
 table(['Le résultat fait bifurquer.','La décision est prise.','La vérification ferme la boucle.'],[
 ['Un danger immédiat est identifié.','Le dispositif médical ou de protection approprié est mobilisé sans attendre le bilan social complet.','La transmission nominative et la prise en charge effective sont confirmées.'],
 ['Aucun danger immédiat n’est constaté, mais la communication est insuffisante.','L’entretien est repris avec l’aide linguistique ou sensorielle nécessaire.','Le patient peut exposer le choix et l’action dans les conditions adaptées.'],
 ['La compréhension s’améliore et une volonté personnelle peut être exprimée.','La décision partagée se poursuit, même si le patient refuse l’option recommandée.','Le médecin vérifie les informations données et les raisons de la décision.'],
 ['Un doute fondé sur le discernement persiste.','Le médecin évalue la décision précise et recherche le cadre de représentation applicable.','Le résultat, les soutiens, les objections et la nécessité de réévaluer sont documentés.'],
 ['Un obstacle d’accès est identifié.','Le patient choisit une action réalisable et l’équipe organise l’aide appropriée.','Le contact, le rendez-vous ou le relais est vérifié avant de considérer l’action accomplie.'],
 ['Une exposition ou une difficulté fonctionnelle contribue au problème.','Le soin clinique et la réduction de la contrainte sont planifiés selon leurs priorités.','Les symptômes et l’effet concret de l’aménagement sont comparés à l’état de départ.'],
 ['L’action ne fonctionne pas ou la situation change.','L’équipe réévalue cause, gravité, acceptabilité et accès réel à l’aide.','Le plan est corrigé avec la personne ; un échec n’est pas automatiquement attribué au patient.']
 ])+refs('S02','S11','S17','S24')))
 s.append((
 'Le but est d’améliorer une fonction ou un accès défini par le patient tout en sécurisant la situation. Les moyens associent soins appropriés, communication adaptée et leviers environnementaux ou sociaux. Le suivi vérifie le résultat réel ; le pronostic dépend de la maladie, des ressources et de l’évolution des obstacles.',
 window('A — Le but doit pouvoir être observé et réévalué.',
 p('Le médecin choisit avec le patient un objectif qui répond à sa priorité. Un objectif chiffré peut être pédagogique lorsqu’il décrit une action convenue, mais il n’est pas présenté comme un seuil officiel de guérison. L’accord précise comment chacun saura que l’action a aidé.')+
 p('Une patiente souhaite reprendre une visite hebdomadaire à sa sœur. L’objectif négocié est de tester un déplacement accompagné, puis d’évaluer fatigue, satisfaction et besoin d’aide. Cette fréquence est son choix dans la vignette ; elle ne constitue pas une prescription universelle.')+refs('S02'))+
 window('B — Les moyens sont engagés dans un ordre explicite.',
 p('L’équipe traite d’abord le danger actuel. Elle assure ensuite les conditions de communication et recueille la préférence. Elle choisit avec la personne un levier principal, organise le relais et confirme qui fait quoi. Les démarches compatibles peuvent avancer en parallèle ; aucune démarche administrative ne retarde les soins urgents.')+
 table(['L’étape est engagée.','L’action est précisée.','La raison est donnée.'],[
 ['La situation est sécurisée.','Le médecin évalue les symptômes et mobilise une aide adaptée à leur gravité.','Un obstacle social ne doit pas masquer une détresse clinique.'],
 ['La communication est rendue possible.','L’interprète ou le support adapté est organisé avant une décision complexe lorsque le besoin est établi.','L’accord n’est valable que si l’échange permet réellement de décider.'],
 ['Le plan est négocié.','Le patient identifie sa priorité, les options et ce qu’il accepte d’essayer.','L’intervention doit être pertinente et réalisable dans sa vie.'],
 ['Le relais est organisé.','Le professionnel responsable accepte la transmission et le patient sait comment le joindre.','Une simple liste de numéros ne prouve pas que le soin est accessible.'],
 ['Le traitement de la maladie est coordonné.','Le prescripteur vérifie indication, tolérance et interactions sur les sources adaptées.','Une difficulté sociale ne doit pas conduire à ajouter un psychotrope par défaut.']
 ])+p('Aucun médicament ne traite à lui seul ce SSP. Les posologies, spécialités et adaptations d’antidépresseurs nécessitent une fiche de l’information professionnelle suisse effectivement lue ; à cette étape, elles sont indiquées « À vérifier (AIPS) ». Aucun dosage issu de la SPEC ancienne n’est repris comme validé.')+refs('S02','S07','S21','S23'))+
 window('L’urgence suit une chronologie clinique plutôt qu’un minutage inventé.',
 p('Dès la constatation du danger, le médecin évalue la conscience et l’état clinique et sollicite l’aide médicale immédiate. Dans l’exemple thermique avec altération de conscience ou impossibilité de boire, il appelle le 144 et commence le rafraîchissement. En parallèle, l’équipe rassemble les informations indispensables, les traitements actuels et les éléments de volonté ou de représentation. Avant le transfert, elle confirme le professionnel receveur et les informations nécessaires. Après la prise en charge initiale, elle réévalue l’obstacle qui a contribué à la crise.')+
 p('Lors d’un malaise à la chaleur, le rafraîchissement et l’aide urgente ne doivent pas attendre la résolution d’un problème de transport ou de paiement. Une personne inconsciente ne reçoit pas une boisson par la bouche. Les gestes et traitements spécifiques relèvent du protocole clinique applicable ; aucun délai minute par minute n’est inventé ici.')+refs('S11','S32','S24'))+
 window('Les situations spéciales sont intégrées au plan.',
 table(['La situation particulière est rencontrée.','Le médecin adapte le plan.','La limite est précisée.'],[
 ['La patiente est enceinte ou allaite.','Les besoins de soutien, les conditions de logement et la coordination des soins sont explorés avec elle.','Une prescription ne se déduit pas d’un conseil psychosocial ; l’AIPS et la recommandation propre au traitement sont vérifiées.'],
 ['Le patient est âgé ou dépendant.','L’équipe vérifie l’aide disponible, les capacités sensorielles, la charge du parcours et les risques d’exposition.','L’âge n’entraîne pas à lui seul une incapacité de discernement.'],
 ['Le patient est un enfant ou un adolescent.','Le médecin s’adresse à lui de façon adaptée et organise un espace de parole propre.','Le discernement et la représentation sont évalués pour la décision précise ; aucun âge de transfert universel n’est inventé.'],
 ['La fonction rénale ou cardiaque limite les apports.','Le médecin individualise l’hydratation pendant une période chaude et clarifie le plan médicamenteux.','Le conseil général de boire davantage ne remplace pas la prescription personnelle.'],
 ['Une insuffisance hépatique ou une polymédication est connue.','Le prescripteur réévalue les traitements réellement pris et les risques de l’ensemble.','Les adaptations chiffrées ne sont pas déduites du seul diagnostic ; elles restent à vérifier dans l’AIPS.']
 ])+refs('S11','S17','S18','S23'))+
 window('C — La surveillance vérifie l’action, sa tolérance et la sécurité.',
 p('La surveillance porte sur le symptôme clinique pertinent, le retentissement choisi et l’accès au relais. La date de contrôle est convenue selon le risque et les contraintes. Le dossier précise les signes qui imposent une réévaluation plus rapide et le professionnel à joindre.')+
 p('Le patient et l’équipe vérifient séparément la réception de l’information, la possibilité d’agir et l’effet obtenu. Une aide refusée ou inaccessible conduit à une nouvelle discussion. Un effet indésirable ou une aggravation clinique justifie un examen médical et une révision du plan.')+refs('S02','S09','S21'))+
 window('D — La sortie exige un environnement compatible avec le plan.',
 p('La sortie n’est pas décidée sur la seule stabilité d’un indicateur biologique. L’équipe vérifie que le problème aigu a été évalué, que le traitement est compris, que les besoins essentiels peuvent être couverts et qu’un suivi adapté est organisé. La personne peut dire quoi faire si la situation se dégrade.')+
 table(['Le critère de sortie est vérifié.','La preuve concrète est recherchée.'],[
 ['Le besoin clinique immédiat est couvert.','Le médecin documente l’évaluation et les raisons qui permettent la poursuite hors hospitalisation.'],
 ['La décision et le plan sont compris dans une communication adaptée.','Le patient ou le représentant applicable peut expliquer les actions retenues.'],
 ['Les moyens nécessaires sont disponibles.','Les médicaments, aides, transport et lieu de séjour sont vérifiés selon le cas.'],
 ['Le proche n’est pas chargé d’une tâche qu’il ne peut pas assumer.','Le relais accepte les responsabilités convenues et les besoins de décharge sont traités.'],
 ['Le suivi et la réponse à une aggravation sont définis.','Le nom du professionnel, le moyen de contact et les motifs de réévaluation sont connus.']
 ])+p('Ces critères constituent une synthèse pédagogique du raisonnement de sortie ; ils ne remplacent pas les critères spécifiques de la maladie aiguë. Le SSP ne comporte pas de test de guérison. En 2026, le développement du soutien à l’autogestion et de ses standards poursuit un objectif d’intégration sanitaire et sociale ; aucun essai ou bénéfice chiffré non vérifié n’est annoncé.')+refs('S02','S03','S09','S17'))))
 s.append((
 'La prévention primaire réduit les expositions et rend les informations utilisables avant une complication. La prévention secondaire repère tôt les obstacles, la détresse et les besoins de soutien. La prévention tertiaire vise une participation durable et réduit les ruptures de suivi, sans promettre d’effacer toute maladie chronique.',
 table(['Le niveau de prévention est appliqué.','Le médecin propose une action.','Le résultat est vérifié.'],[
 ['La prévention primaire est organisée.','L’équipe propose un langage compréhensible, un logement moins exposant et une préparation aux épisodes de chaleur.','La personne peut utiliser le message et sait quelles protections lui conviennent.'],
 ['La prévention secondaire est ciblée.','Le médecin recherche un renoncement, une souffrance psychique ou une charge d’aide qui augmente.','Une difficulté identifiée débouche sur une évaluation et une action réalisable.'],
 ['La prévention tertiaire soutient la participation.','L’équipe coordonne réadaptation, aides et continuité des soins avec la personne.','La fonction choisie et le maintien du parcours sont réévalués au lieu de compter seulement les contacts.']
 ])+refs('S02','S09','S11','S18','S19')+
 dossier('La prévention ne doit pas augmenter la charge qui empêche déjà de se soigner.',
 'Une proposition supplémentaire peut être utile mais impossible à réaliser dans l’immédiat. La prévention doit tenir compte de la maladie, du budget, du temps et de l’aide réellement disponibles.',
 'Le médecin hiérarchise les actions avec la personne, vérifie les contraintes puis choisit une étape qui ne compromet pas les soins essentiels. Il revoit ce choix si la situation change. Les vaccinations et dépistages propres à une maladie sont recherchés dans leurs recommandations spécifiques plutôt que copiés sans indication.',
 'Un homme de 52 ans cumule des rendez-vous et n’arrive plus à travailler. L’équipe regroupe les démarches et choisit d’abord l’action la plus utile à sa priorité clinique. Elle évite d’ajouter simultanément plusieurs programmes que personne ne pourra suivre.',
 'confondre multiplication des conseils et qualité de la prévention.',['S02','S03','S19'])))
 s.append((
 'Le médecin examine tout symptôme nouveau avant de l’attribuer au contexte psychosocial. Il recherche les ressources autant que les difficultés. Il rend la décision compréhensible et respecte une volonté capable de discernement. Il organise une action concrète et un relais accepté. Il réévalue l’effet réel du plan et corrige les obstacles persistants.',
 table(['Le candidat formule le message.','Il l’applique au cas.'],[
 ['Le diagnostic médical et la situation de vie sont examinés ensemble.','Le candidat distingue ce qu’il sait, ce qu’il suppose et ce qu’il doit vérifier.'],
 ['Une donnée populationnelle ne décrit pas automatiquement la personne présente.','Le candidat cite le dénominateur avant de donner un pourcentage.'],
 ['Un proche, une institution et un employeur n’ont pas les mêmes droits d’information.','Le candidat vérifie l’accord et la base juridique avant une transmission.'],
 ['L’urgence passe avant la complétude administrative.','Le candidat mobilise les soins nécessaires et traite les obstacles compatibles en parallèle.'],
 ['Un plan n’est réalisé que si son accès et son effet sont vérifiés.','Le candidat confirme le relais et prévoit la réévaluation.']
 ])+refs('S01','S02','S17','S24','S28')))
 s.append((
 'Les questions suivantes entraînent au raisonnement attendu par PROFILES ; elles ne prétendent pas reproduire des questions officielles de l’examen. Chaque réponse relie une décision à un élément discriminant et à sa limite. Le candidat évite les certitudes que les sources ne permettent pas.',
 questions_exam()+refs('S01','S04','S05','S07','S09','S11','S14','S17','S18','S24','S25','S26','S27','S28','S29')))
 return s

def questions_exam():
 qs=[
 ('Une patiente refuse le soin proposé. Peut-on en déduire qu’elle est incapable de discernement ?', 'Le refus ne suffit pas. Le candidat examine la décision précise, les capacités nécessaires et les conditions de communication ; il respecte ensuite la volonté exprimée si la personne est capable de discernement.'),
 ('Une consultation se déroule difficilement dans une langue peu maîtrisée. Quel est le premier levier ?', 'Le candidat adapte la communication et organise l’interprétariat professionnel si nécessaire. Il ne tire pas une conclusion cognitive d’un obstacle linguistique.'),
 ('Le proche aidant est présent au cabinet. Peut-on lui communiquer tout le dossier ?', 'Le candidat vérifie ce que le patient autorise et recherche, si besoin, une base de représentation ou une disposition légale. La présence et l’aide pratique ne lèvent pas le secret professionnel.'),
 ('Une personne malade chronique ne vient plus. Le dossier indique « non observante ». Quelle donnée manque ?', 'Le candidat recherche ce qui a empêché la venue : coût, transport, compréhension, préférence, effets du traitement ou surcharge. Il remplace l’étiquette par une explication vérifiable.'),
 ('La fiche indique que 49 % des adultes ont une littératie faible. Peut-on l’appliquer à un patient donné ?', 'Le candidat présente le résultat comme une donnée d’enquête, puis vérifie la compréhension du patient. Il ne le transforme pas en probabilité individuelle ni en critère de discernement.'),
 ('Une personne âgée sous traitement cardiaque reçoit le conseil de boire sans limite pendant une canicule. Que corriger ?', 'L’hydratation doit être individualisée avec le médecin lorsqu’une maladie cardiaque ou rénale le nécessite. Le candidat ne remplace pas le plan personnel par un conseil général.'),
 ('Le radon atteint 450 Bq/m³ dans une pièce de séjour. Le seuil de 1 000 Bq/m³ du travail suffit-il à rassurer ?', 'Le candidat distingue le niveau de référence de 300 Bq/m³ des locaux régulièrement occupés et le seuil particulier des postes de travail exposés au radon. Il oriente vers une évaluation de la mesure et de l’assainissement ; il ne transpose pas un seuil à tous les locaux.'),
 ('Une mesure d’air est inférieure à une limite légale. Prouve-t-elle l’absence de risque individuel ?', 'Le candidat distingue une règle d’immission, une exposition personnelle et un diagnostic clinique. Le respect d’une limite n’explique ni n’exclut à lui seul les symptômes.'),
 ('Un arrêt de travail de 50 % garantit-il une rente AI de 50 % ?', 'Le candidat distingue incapacité de travail, invalidité et quotité de rente. L’assurance-invalidité examine ses conditions légales et les possibilités de réadaptation ; le certificat n’attribue pas une rente.'),
 ('Une aide familiale arrive à épuisement. Quel est le résultat attendu du premier entretien ?', 'Le candidat identifie les tâches et le besoin de décharge, évalue la sécurité puis convient d’un relais concret. Il ne se contente pas de féliciter le proche ou de lui remettre une liste générale.'),
 ('Un jeune atteint de maladie chronique arrive à la majorité. Le transfert doit-il se faire automatiquement ce jour-là ?', 'Le candidat prépare la continuité avec les équipes et le jeune. Il distingue la majorité civile, la décision de soins et l’organisation locale de transition ; le parcours CHUV lu ne crée pas une règle universelle.'),
 ('Une patiente semble confuse dans un logement très chaud. Peut-on attendre le bilan social ?', 'Le candidat évalue immédiatement la gravité, engage le rafraîchissement et mobilise une aide médicale adaptée. Le travail social se poursuit selon ses possibilités sans retarder la réponse clinique.')
 ]
 cases=[
 ('Une femme de 67 ans explique les conséquences de son refus et maintient sa préférence après une information adaptée.','La divergence de valeurs et une incapacité sont deux questions distinctes. Le médecin décrit les capacités observées plutôt que le caractère raisonnable de sa propre recommandation.','Confondre refus et incapacité retire à tort un pouvoir de décision.',['S17','S24']),
 ('Un patient de 43 ans peut converser au quotidien mais ne comprend pas le choix entre deux interventions.','La complexité de la décision détermine le besoin de soutien ; le niveau de conversation habituel ne garantit pas la compréhension médicale. Le médecin reprend l’entretien avec un interprète et vérifie la reformulation.','Un acquiescement poli peut masquer un défaut d’information.',['S07','S17']),
 ('Le conjoint appelle pour connaître les résultats avant que la patiente les reçoive.','Le médecin précise l’accord de la patiente et le périmètre de la transmission. Le lien familial ne remplace pas cet accord lorsque la personne décide elle-même.','Une aide bienveillante peut néanmoins conduire à une révélation non autorisée.',['S28','S24']),
 ('Un homme de 51 ans reporte des visites parce que son salaire ne permet plus de payer les trajets.','L’échec du parcours est relié à une contrainte précise. La réponse porte sur l’accès et la coordination ; répéter une consigne ne corrige pas le coût.','L’étiquette de désengagement peut rendre l’obstacle invisible.',['S04','S02']),
 ('Une étudiante affirme qu’un patient a 49 % de risque de ne pas comprendre parce qu’une enquête donne cette valeur.','Le dénominateur de l’enquête décrit une population et un instrument. La vérification clinique porte sur la consigne réellement donnée à la personne.','Un pourcentage de groupe ne remplace pas une observation individuelle.',['S05']),
 ('Une patiente de 79 ans suit une restriction hydrique prescrite pour son état cardiaque.','Le médecin confronte le risque thermique et la prescription actuelle, puis individualise le plan avec la patiente. La recommandation de population ne supprime pas les contraintes médicales.','Boire sans limite ou arrêter un traitement spontanément peut ajouter un risque.',['S11']),
 ('Une famille reçoit un résultat annuel de 450 Bq/m³ dans une chambre régulièrement occupée.','Le résultat est comparé à la référence des locaux de séjour. Un seuil propre à un poste exposé au radon répond à une autre catégorie réglementaire. La mesure et les actions sont revues avec un service compétent.','Comparer deux seuils sans vérifier leurs champs d’application donne une fausse assurance.',['S14','S30']),
 ('Un patient consulte pour une dyspnée alors que l’indicateur d’air respecte une limite d’immission.','La mesure environnementale décrit une exposition et une période ; l’examen clinique répond à la question du patient. Le médecin recherche la décompensation et ses causes possibles.','Une norme légale n’est pas un test diagnostique de dyspnée.',['S13','S29','S31']),
 ('Une employée peut rester sur place la moitié de son horaire et demande quelle rente elle recevra.','Le certificat décrit des capacités et des limitations, tandis que l’AI examine la réadaptation et les conséquences économiques selon la loi. Le médecin ne transforme pas un pourcentage de présence en décision d’assurance.','Le taux d’incapacité, le taux d’invalidité et la quotité ne sont pas interchangeables.',['S19','S27']),
 ('Un aidant de 72 ans dit qu’il ne dort plus suffisamment pour continuer la surveillance nocturne.','L’équipe identifie la tâche qui déborde les ressources, vérifie la sécurité et recherche un relais accepté. L’aide devient une responsabilité attribuée, pas une intention vague.','La reconnaissance morale ne remplace pas la décharge.',['S09']),
 ('Un jeune de 17 ans redoute de perdre la pédiatre qui le connaît et n’a pas de rendez-vous adulte.','La transition prépare un lien et une transmission, au lieu de juxtaposer deux courriers. Le discernement et la confidentialité restent appréciés pour chaque décision.','L’anniversaire de majorité ne confirme pas qu’un suivi adulte est effectivement organisé.',['S18','S17','S24']),
 ('Une personne de 82 ans ne peut plus expliquer où elle se trouve alors que le logement reste très chaud.','La gravité présente impose une réponse clinique immédiate. Les informations sur les proches et le logement sont utiles en parallèle, sans retarder l’aide.','Le contexte social peut expliquer une vulnérabilité, mais ne banalise pas une altération de conscience.',['S11','S24'])
 ]
 return ''.join(window(q,p(a)+p('La vignette est fictive. '+cas)+p(mecanisme)+p('Le piège est le suivant : '+piege)+refs(*sources),'cas') for (q,a),(cas,mecanisme,piege,sources) in zip(qs,cases))

def syndrome_windows():
 defs=[
 ('7.1 — Le parcours de soins devient difficile à réaliser.','La personne rapporte une difficulté à obtenir, comprendre ou utiliser les soins nécessaires. Les signes fonctionnels sont son récit de report, de confusion ou d’impossibilité ; les éléments objectivables sont les étapes et aides qu’elle peut décrire ou montrer.','Le médecin lui demande de parcourir une action réelle, depuis la prise de rendez-vous jusqu’au retour à domicile. Le résultat attendu est une séquence réalisable ; une étape impossible indique où intervenir.','Un patient de 54 ans sait expliquer pourquoi consulter mais ne trouve aucun transport au bon horaire. Le problème porte sur le trajet, pas sur son discernement.','un rendez-vous manqué ne prouve pas un manque de motivation.',['S02','S04','S07']),
 ('7.2 — Le soutien devient insuffisant.','Le malade exprime un besoin non couvert ou le proche décrit une charge devenue excessive. Les signes fonctionnels sont la fatigue ressentie, le sentiment d’être seul et l’impossibilité de continuer ; l’évaluation objective les tâches, leur fréquence et les relais acceptés.','Le médecin remplit avec le proche la grille OFSP et compare charge, aides actuelles et besoins. Il recherche ensuite quelle tâche doit être reprise et par qui. Le résultat n’est pas un score diagnostique de burnout.','Une aidante de 65 ans peut assurer les repas mais plus les nuits. Le relais demandé cible la surveillance nocturne au lieu de doubler une aide ménagère déjà suffisante.','la présence d’un proche ne garantit pas qu’il puisse tout assurer.',['S09','S10']),
 ('7.3 — L’exposition physique aggrave la vulnérabilité.','Le patient rapporte un lien entre un contexte physique et ses symptômes. Les signes fonctionnels sont le malaise, la gêne respiratoire ou les irritations ; l’examen recherche d’abord l’absence de détresse puis les anomalies qui demandent un bilan médical.','Le médecin confronte le lieu, la période, les traitements et les autres causes possibles. Il ne réalise une mesure environnementale que si la question est définie. Une exposition plausible et une maladie aiguë peuvent coexister.','Un homme de 71 ans se sent plus essoufflé près d’un axe routier. Le médecin examine la dyspnée avant d’organiser une réduction d’exposition.','une association temporelle ne démontre pas une causalité unique.',['S11','S13','S16']),
 ('7.4 — La participation professionnelle ou scolaire se réduit.','La personne rapporte une activité devenue impossible ou un parcours de formation perturbé. Les signes fonctionnels sont les difficultés décrites ; l’évaluation précise la tâche, le temps disponible, le rendement et les aménagements possibles.','Le médecin compare les exigences concrètes au fonctionnement observé et rapporté. Il vérifie avec la personne une adaptation réaliste, puis documente ce qui sera réévalué. Le diagnostic seul ne détermine pas toutes les capacités.','Une jeune de 18 ans peut suivre sa formation mais manque les consultations quand elles tombent pendant un examen. Le service organise un relais et un horaire compatible, sans conclure à une incapacité scolaire générale.','l’absence d’adaptation peut être confondue avec une incapacité médicale totale.',['S18','S19'])
 ]
 return ''.join(window(t,p(d)+p(proc)+p('La vignette est fictive. '+ex)+p('Le piège est le suivant : '+pi)+refs(*src)) for t,d,proc,ex,pi,src in defs)

def annexes_a():
 return '<section id="atelier"><h3><strong>Le raisonnement se vérifie dans des situations appliquées.</strong></h3>'+p('Les cas suivants sont des constructions pédagogiques. Leurs âges, durées et décisions de planification illustrent une méthode ; ils ne constituent pas des seuils diagnostiques ou des données épidémiologiques.')+atelier_cases()+legal_toolkit()+'</section>'

def atelier_cases():
 cases=[
 ('Le coût empêche une décision pourtant comprise.','Une femme de 60 ans suit une maladie chronique. Elle décrit correctement son plan mais a reporté trois démarches parce qu’elle ne pouvait pas avancer les montants.','Le candidat commence par vérifier la nécessité et la gravité des soins reportés. Il demande ensuite quelles sommes et quelles prestations posent problème, puis explore la couverture et les aides avec le service social.','Le médecin ne promet pas un remboursement avant vérification. Il convient d’une action avec un responsable et une échéance adaptée au risque. Il confirme que le contact est obtenu.','Si le coût ne peut pas être résolu immédiatement, le médecin réévalue un plan de soins accessible sans supprimer un soin essentiel. Le résultat attendu est un accès réel, pas un formulaire simplement rempli.',['S04','S20','S26']),
 ('Une communication adaptée modifie l’hypothèse.','Un homme de 46 ans acquiesce sans expliquer les choix proposés. Sa fille répond à toutes les questions.','Le candidat propose un temps où le patient peut s’exprimer lui-même et organise, si nécessaire, un interprète professionnel. Il vérifie la langue préférée et reprend la décision avec des informations limitées à l’essentiel.','Le médecin évalue ensuite la compréhension et la volonté dans ces nouvelles conditions. Une difficulté persistante peut justifier une évaluation du discernement ; la première impression ne suffit pas.','Le résultat attendu est une décision personnelle ou une évaluation documentée des capacités, et non une conclusion fondée sur l’origine ou l’aisance verbale.',['S07','S17','S24','S28']),
 ('Une décharge est définie avant le retour à domicile.','Un proche de 70 ans accepte le retour d’une personne dépendante mais explique qu’il ne peut plus assurer les transferts et la garde nocturne.','Le candidat sépare l’accord affectif et la capacité concrète. Il identifie les tâches, les horaires et les risques, puis vérifie quels professionnels ou proches peuvent effectivement prendre le relais.','Le médecin ne donne pas pour consigne de « surveiller davantage ». Il s’assure que les moyens existent et que la personne malade accepte les modalités compatibles avec ses droits.','Le résultat attendu est un plan dont les tâches sont attribuées et acceptées. Si un besoin essentiel reste découvert, l’équipe revoit les conditions de sortie.',['S09','S17','S24']),
 ('L’exposition au logement n’efface pas le raisonnement clinique.','Deux occupants décrivent des irritations qui augmentent dans une pièce humide. L’un d’eux présente une maladie respiratoire connue.','Le candidat précise les symptômes, leur chronologie et l’état clinique actuel. Il recherche aussi les facteurs du bâtiment et les démarches déjà faites ; il n’attribue pas tous les symptômes à une moisissure visible.','Le médecin conseille une démarche ciblée : bilan médical, signalement écrit des dégâts, avis technique adapté et suivi de l’effet des corrections. Les tests de polluants non ciblés ne sont pas un premier réflexe.','Le résultat attendu est une hypothèse documentée et une correction pertinente. Une amélioration après éviction contribue au raisonnement mais ne prouve pas à elle seule le mécanisme exact.',['S15','S16']),
 ('Le travail est adapté sans transformer un certificat en rente.','Une personne de 55 ans peut accomplir certaines tâches mais ne supporte plus le rythme complet de son poste habituel.','Le candidat décrit les fonctions utiles, les exigences et les restrictions. Il sépare le temps de présence et le rendement, puis cherche avec la personne les possibilités de reprise compatible.','Le médecin transmet les éléments nécessaires dans le cadre autorisé et oriente vers les interlocuteurs appropriés. Il n’informe pas l’employeur de tous les diagnostics et ne garantit pas une prestation d’assurance.','Le résultat attendu est un profil fonctionnel intelligible et une réévaluation planifiée ; l’ouverture d’un droit reste une décision de l’organisme compétent.',['S19','S27','S28']),
 ('La transition associe autonomie et continuité.','Un adolescent de 17 ans connaît son traitement, mais ses parents organisent tous les rendez-vous et aucune équipe adulte n’est encore identifiée.','Le candidat lui demande ce qu’il souhaite décider et ce qu’il préfère encore partager. Il clarifie le discernement pour les décisions nécessaires et prépare un contact nominatif avec l’équipe suivante.','Le médecin vérifie les documents utiles, le rendez-vous et le moyen de demander de l’aide pendant l’intervalle. La participation des parents est discutée avec le jeune dans le respect des règles applicables.','Le résultat attendu est une continuité effective et une progression choisie des responsabilités. L’âge seul ne remplace pas cette préparation.',['S18','S17','S24'])
 ]
 return ''.join(window(t,p('La vignette suivante est fictive. '+cas)+p(a)+p(b)+p(c)+refs(*src),'cas') for t,cas,a,b,c,src in cases)

def legal_toolkit():
 import json
 from pathlib import Path
 root=Path(__file__).resolve().parent
 out='<section><h3><strong>Le lecteur distingue les articles applicables et leurs limites.</strong></h3>'+p('Cette annexe réunit les passages légaux ciblés qui ont été ouverts dans la consolidation officielle applicable à la date de consultation. Les citations légales sont séparées des explications pédagogiques ; les règles cantonales particulières restent à vérifier selon le cas.')
 explanations={
 'art_16':('Le médecin apprécie la faculté de décider dans les conditions de la consultation et pour le choix envisagé. Il corrige les obstacles de communication et documente un doute fondé avant de conclure.','Un adulte refuse une option après avoir correctement décrit ses conséquences pour lui ; le médecin respecte ce choix s’il constate les capacités nécessaires.','Le caractère inhabituel du choix ne prouve pas une incapacité.'),
 'art_19_c':('Le médecin distingue majorité, exercice des droits civils et droits strictement personnels. Il apprécie le discernement du jeune pour l’acte envisagé et vérifie les exceptions légales si elles sont pertinentes.','Un jeune demande à discuter seul d’un traitement. Le médecin lui donne un espace de parole et évalue sa compréhension ; il ne transmet pas automatiquement le contenu aux parents.','Être mineur ne rend pas systématiquement incapable de décider d’un soin.'),
 'art_378':('Le médecin vérifie d’abord les directives anticipées et la personne désignée, puis suit l’ordre légal de représentation et ses conditions. En l’absence d’instructions, la décision respecte la volonté présumée et les intérêts de la personne.','Une personne est incapable de discernement et deux proches demandent à décider. Le médecin recherche une désignation préalable et le rang applicable, puis documente les éléments vérifiés.','Le proche le plus insistant ne devient pas représentant par sa seule présence.'),
 'art_379':('En urgence, le médecin détermine les soins nécessaires en fonction de la volonté présumée et des intérêts de la personne incapable de discernement. Il rassemble les informations disponibles sans retarder la réponse urgente.','Une personne est inconsciente lors d’une décompensation ; l’équipe ne diffère pas les soins urgents pour attendre la résolution de tous les échanges familiaux.','L’urgence ne constitue pas une autorisation générale de négliger toute volonté connue.'),
 'art_443':('Le médecin identifie le besoin de protection, les possibilités d’aide et la règle cantonale applicable. Il vérifie le secret professionnel et la base d’une transmission avant un signalement qui n’est pas déjà autorisé.','Un adulte vulnérable paraît ne plus pouvoir couvrir ses besoins essentiels ; l’équipe documente les faits et sollicite les compétences adaptées, en vérifiant le cadre d’information.','Le droit général d’aviser l’autorité ne supprime pas à lui seul le secret professionnel.'),
 'art_329_h':('Le salarié et l’employeur examinent le temps nécessaire à la prise en charge dans le champ du texte. Le médecin documente le besoin médical pertinent ; il ne certifie pas un congé sans rapport avec la situation constatée.','Une salariée doit aider un membre de sa famille atteint dans sa santé. Elle vérifie avec l’employeur comment le congé de prise en charge s’applique à son cas.','Ce congé n’est pas un crédit automatique de dix jours à utiliser sans nécessité.'),
 'art_329_i':('Le médecin distingue le congé court du congé pour enfant gravement atteint dans sa santé. Les conditions de l’allocation correspondante et la répartition sont examinées avec les interlocuteurs compétents.','Deux parents salariés demandent comment organiser la prise en charge d’un enfant gravement malade ; l’équipe les oriente pour vérifier le droit et la répartition, au lieu de promettre quatorze semaines à chacun.','Le plafond total ne doit pas être doublé par une lecture erronée du partage entre parents.'),
 'art_336_c':('Le médecin précise les faits médicaux nécessaires au certificat. Le régime du contrat, le temps d’essai, l’année de service et les dates sont vérifiés pour apprécier une protection contre la résiliation.','Un salarié demande si un arrêt médical annule son licenciement. Le médecin distingue le constat d’incapacité et la conséquence juridique ; il l’oriente vers une analyse du contrat et des dates.','Les périodes de trente, quatre-vingt-dix ou cent quatre-vingts jours ne garantissent pas le salaire pendant la même durée.'),
 'art_64':('L’équipe distingue prime, franchise, quote-part et contribution hospitalière. Elle vérifie les prestations, l’année et les exceptions avant d’estimer un reste à charge.','Une patiente reporte un soin parce qu’elle confond la prime mensuelle et la franchise annuelle ; le service social reprend le décompte avec elle.','Le montant ordinaire n’exclut pas les exceptions légales ou la quote-part différenciée de certains médicaments.'),
 'art_65':('Le patient et le service social vérifient les conditions cantonales et la situation économique actuelle. La demande et son état de traitement sont suivis sans présumer un montant individuel de subside.','Un patient dont le revenu a diminué demande une réduction de prime ; l’équipe l’oriente vers le service cantonal et vérifie les pièces nécessaires.','La loi fédérale ne permet pas de déduire automatiquement un montant personnel à partir d’un revenu isolé.'),
 'art_28':('L’AI examine la réadaptation, l’incapacité de travail et l’invalidité selon les conditions cumulatives. Le médecin documente l’atteinte, la fonction et l’évolution, sans décider lui-même du droit à la rente.','Une personne ayant une maladie chronique demande une rente dès le diagnostic. Le médecin décrit les limitations et explique le rôle de la réadaptation et de l’office AI.','Une année de maladie ne suffit pas si les autres conditions légales ne sont pas remplies.'),
 'art_28_b':('L’office distingue le taux d’invalidité et la quotité de la rente dans le système applicable. Pour une rente ancienne, les dispositions transitoires doivent être examinées avant d’appliquer le barème linéaire.','Dans le barème lu, un taux d’invalidité de 45 % correspond à 37,5 % d’une rente entière ; ce n’est ni une estimation clinique ni un montant en francs.','Le taux d’incapacité de travail ne se substitue pas au taux d’invalidité.'),
 'art_321':('Le médecin vérifie le consentement, une autorisation de l’autorité compétente ou une disposition légale particulière avant de révéler des informations. Il adapte la transmission à son objet.','Un employeur demande les diagnostics pour aménager un poste ; le médecin vérifie le cadre autorisé et privilégie les informations fonctionnelles nécessaires.','L’utilité présumée de la transmission ne suffit pas à lever le secret.')
 }
 for path in sorted((root/'evidence').glob('S2[4-9]_*.json')):
  d=json.loads(path.read_text()); body=p('Le texte consolidé consulté porte la date suivante : '+d['year']+'.')
  for ex in d['extraits']:
   if ex['id']=='annex_7':
    body+=window('L’annexe 7 fixe des valeurs d’immission et non des critères de diagnostic.',p('Le texte OPair lu fixe des moyennes d’immission. Une concentration doit être reliée à sa période de moyenne : une moyenne annuelle ne se compare pas à une pointe horaire.')+table(['Le polluant est défini.','La limite OPair est lue.','La recommandation distincte est comparée.'],[['Les particules PM2,5 ont un diamètre aérodynamique inférieur à 2,5 µm.','La moyenne annuelle est limitée à 10 µg/m³.','L’OMS 2021 et la CFHA 2023 proposent 5 µg/m³.'],['Les particules PM10 ont un diamètre aérodynamique inférieur à 10 µm.','La moyenne annuelle est limitée à 20 µg/m³.','L’OMS 2021 et la CFHA 2023 proposent 15 µg/m³.'],['Le dioxyde d’azote est un polluant gazeux.','La moyenne annuelle est limitée à 30 µg/m³.','L’OMS 2021 et la CFHA 2023 proposent 10 µg/m³.'],['L’ozone est comparé à une moyenne horaire.','La valeur de 120 µg/m³ ne doit pas être dépassée plus d’une fois par année.','Une valeur saisonnière ou sur huit heures répond à une autre définition.']])+p('La vignette est fictive. Un patient compare un pic horaire de particules à la valeur annuelle. Le médecin corrige l’échelle temporelle et examine les symptômes indépendamment de cette comparaison.')+p('Le piège consiste à annoncer comme droit en vigueur une recommandation scientifique qui n’a pas été intégrée à l’ordonnance. La référence légale reste l’OPair consultée ; la recommandation indique un objectif de protection distinct.')+refs('S29','S31'))
    continue
   text=ex['texte_lu']
   proc,case,trap=explanations[ex['id']]
   body+=window('Le passage '+ex['id'].replace('art_','article ').replace('_',' ')+' précise la règle.',p(proc)+p('La vignette est fictive. '+case)+p('Le piège est le suivant : '+trap)+window('Le lecteur peut contrôler le texte officiel exact.',p('<em>Le texte officiel lu est reproduit ci-dessous.</em>')+'<blockquote>'+p(__import__('html').escape(text))+'</blockquote>')+refs(d['id']))
  body+=refs(d['id'])
  legal_names={'S24':'Les articles ciblés du Code civil encadrent la décision.','S25':'Les articles ciblés du Code des obligations précisent les droits du travail.','S26':'Les articles ciblés de la loi sur l’assurance-maladie encadrent la participation et les aides.','S27':'Les articles ciblés de la loi sur l’assurance-invalidité distinguent les conditions et la quotité.','S28':'L’article du Code pénal protège le secret professionnel.','S29':'L’annexe de l’ordonnance sur la protection de l’air fixe des valeurs d’immission.'}
  out+=window(legal_names[d['id']],body)
 return out+'</section>'
